let windowSize = 1h;

// S41: Malicious GCS Mission Upload — UAVMissionPlan_CL, UAVId 보유
let S41 =
    UAVMissionPlan_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('upload','mission_upload') or isnotempty(FailReason)
    | extend Stage = 'S41', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S47: MAVROS Command Injection — UAVCompanion_CL엔 UAVId 없음, Target을 대리키로 사용
let S47 =
    UAVCompanion_CL
    | where TimeGenerated > ago(windowSize)
    | where InjectionSignatureDetected == true
    | extend Stage = 'S47', UAVId = tostring(Target)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S84: Forged C4I Command — UAVC4I_CL엔 UAVId 없음, TargetId를 대리키로 사용
let S84 =
    UAVC4I_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'forged_command' or Source == 'forged'
    | extend Stage = 'S84', UAVId = tostring(TargetId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S41, S47, S84
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 2
| extend CampaignType = "C19_GCS악성미션_MAVROS명령주입_C4I위조"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
